<template>
  <div class="container template_write" v-loading="loading">
    <div class="vote_add_top" @click="return_vote_list_add">
      <i class="el-icon-arrow-left"></i>&nbsp;&nbsp;返回
    </div>
    <div class="box-limit">
        <div class="container-box">
          <div class="editbox">
            <!-- 标题 -->
            <div class="title">
              <div class="title_box">
              {{template_title}}
              </div>
            </div>
            <div class="list" id="list" :style="{'font-size':'14px',backgroundImage: template_img, width: template_width, backgroundSize : '100% auto', backgroundRepeat: 'no-repeat'}">
              <img :src="template_img_box" ref="template_img_box_display" :style="{width: template_width, 'height': 'auto'}">
              <div v-for="(rect, index) in rects" :key="index">
                <div :style="{position: 'absolute','-webkit-box-sizing': 'border-box','box-sizing': 'border-box',top: rect.top+'px', left: rect.left+'px', width: rect.width+'px', height: rect.height+'px'}">
                  <input class="filler" v-if="rect['type'] && rect['type']=='txt'" type="text" :placeholderStyle="{color:'#000'}" :style="{backgroundColor:rect.backgroundColor,color:'#000', width:rect.width+'px', height:rect.height+'px', boxShadow:'0 2px 10px #999'}" v-model="rect['value']" :placeholder="rect['type_text']"/>
                  <input class="filler" v-if="rect['type'] && rect['type']=='title_txt' && !rect['value']" type="text" :style="{color:'#000', width:rect.width+'px', height:rect.height+'px'}" value="请前往填写对应标题" placeholder="请前往填写对应标题" readonly/>
                  <input class="filler" v-if="rect['type'] && rect['type']=='title_txt' && rect['value']" type="text" :style="{color:'#000', width:rect.width+'px', height:rect.height+'px'}" v-model="rect['value']" :placeholder="rect['type_text']" readonly/>
                  <textarea
                    class="filler"
                    v-if="rect['type'] && rect['type']=='mul_txt'"
                    :style="{'z-index': rect.zIndex+1,overflow:'hidden',resize:'none','padding':'5px','text-align': 'left',backgroundColor:rect.backgroundColor,color:'#000', width:(rect.width-10)+'px', height:(rect.height-10)+'px', boxShadow:'0 2px 10px #999'}"
                    :placeholder="rect['type_text']"
                    v-model="rect['value']">
                  </textarea>
                  <el-date-picker
                    style="opacity:0;"
                    :style="{'z-index': rect.zIndex+1,lineHeight:rect.height+'px', backgroundColor:rect.backgroundColor,color:'#000', width:rect.width+'px', height:rect.height+'px', boxShadow:'0 2px 10px #999'}"
                    class="filler"
                    :editable="false"
                    value-format="yyyy-MM-dd"
                    format="yyyy-MM-dd"
                    v-model="rect['value']" v-if="rect['type'] && rect['type']=='date_choose'"
                    type="date"
                    size="mini"
                    :placeholder="rect['type_text']">
                  </el-date-picker>
                  <div class="filler" v-if="rect['type'] && rect['type']=='date_choose'" style="text-align: -webkit-center;" :style="{backgroundColor:rect.backgroundColor,color:'#000', width:rect.width+'px', height:rect.height+'px',lineHeight:rect.height+'px', boxShadow:'0 2px 10px #999'}">
                    <span v-if="rect['value']">{{rect['value']}}</span>
                    <span v-if="!rect['value']">{{rect['type_text']}}</span>
                  </div>
                  <div class="filler" @click="template_add(rect, index)" v-if="rect['type'] && rect['type']!='owner_identity' && rect['type']!='txt' && rect['type']!='date_choose' && rect['type']!='mul_txt' && rect['type']!='title_txt'" style="text-align: -webkit-center;" :style="{backgroundColor:rect.backgroundColor,color:'#000', width:rect.width+'px', height:rect.height+'px',lineHeight:rect.height+'px', boxShadow:'0 2px 10px #999'}">
                    <span v-if="rect['value']">{{rect['value']}}</span>
                    <span v-if="!rect['value']">{{rect['type_text']}}</span>
                  </div>
                  <!-- <div class="filler" @click="template_identity_add(rect, index)" v-if="rect['type'] && rect['type']=='owner_identity'" style="text-align: -webkit-center;" :style="{backgroundColor:rect.backgroundColor,color:'#000', width:rect.width+'px', height:rect.height+'px',lineHeight:rect.height+'px', boxShadow:'0 2px 10px #999'}">
                    <span v-if="rect['value']">{{rect['value']}}</span>
                    <span v-if="!rect['value']">{{rect['type_text']}}</span>
                  </div> -->
                  <el-select v-model="rect['value']" :popper-class='owner_identity_select' :placeholder="rect['type_text']" v-if="rect['type'] && rect['type']=='owner_identity'" :style="{backgroundColor:rect.backgroundColor,color:'#000', width:rect.width+'px', height:rect.height+'px',lineHeight:rect.height+'px', boxShadow:'0 2px 10px #999'}">
                    <el-option
                      v-for="item in owner_identity_options"
                      :key="item.value"
                      :label="item.label"
                      :value="item.value">
                    </el-option>
                  </el-select>
                  <div v-if="rect['type'] && rect['type']!='title_txt'" class="close_block" @click="close_block(index)" :style="{'z-index':rect.zIndex+2}">×</div>
                </div>
              </div>
            </div>

            <div class="list" ref="list_box"  style="display: none;" :style="{'font-size':'16px',backgroundImage: template_img, width: template_width, backgroundSize : '100% auto', backgroundRepeat: 'no-repeat'}">
              <img :src="template_img_box" ref="template_img_box_display" :style="{width: template_width, 'height': 'auto'}">
              <div v-for="(rect, index) in rects" :key="index">
                <div :style="{position: 'absolute','-webkit-box-sizing': 'border-box','box-sizing': 'border-box',top: rect.top+'px', left: rect.left+'px', width: rect.width+'px', height: rect.height+'px'}">
                  <!-- <div class="filler" v-if="rect['type'] && rect['type']=='mul_txt'" style="text-align: -webkit-left;" :style="{'z-index': rect.zIndex+1,overflow:'hidden','padding':'5px','text-align': 'left', width:(rect.width-10)+'px', height:(rect.height-10)+'px'}">
                    <span v-if="rect['value']">{{rect['value']}}</span>
                    <span v-if="!rect['value']">{{rect['type_text']}}</span>
                  </div> -->
                  <textarea
                    class="filler"
                    v-if="rect['type'] && rect['type']=='mul_txt'"
                    :style="{'z-index': rect.zIndex+1,overflow:'hidden',resize:'none','padding':'5px','text-align': 'left',color:'#000', width:(rect.width-10)+'px', height:(rect.height-10)+'px'}"
                    :placeholder="rect['type_text']">{{rect['value']}}</textarea>
                  <div class="filler" v-if="rect['type'] && rect['type']!='mul_txt'" style="text-align: -webkit-center;" :style="{width:rect.width+'px', height:rect.height+'px',lineHeight:rect.height+'px'}">
                    <span v-if="rect['value']">{{rect['value']}}</span>
                    <span v-if="!rect['value']">{{rect['type_text']}}</span>
                  </div>
                </div>
              </div>
            </div>


          </div>

          <div class="add">
            <div class="addbox">
              <el-row style="line-height: 28px;text-align: left;" v-if="diy_id>0">
                <el-col :span="8">
                  押金绑定：
                </el-col>
                <el-col :span="16">
                  <el-button class="save_btn" size="mini" type="primary" @click="choose_diy_deposit()">点击选择押金</el-button>
                </el-col>
              </el-row>
              <!-- bind_deposit_info -->
              <el-row style="line-height: 28px;text-align: left;" v-if="!diy_id" >
                填写信息保存后请在对应的填写记录中绑定押金
              </el-row>
              <div v-if="diy_id" style="margin-top:12px;">
                <el-row style="line-height: 28px;text-align: left;"  v-for="(deposits, indexs) in bind_deposit_info" :key="indexs">
                  <el-tag type="success" @close="handleTagClose(deposits)" closable style="margin-top:8px;">{{deposits.name}} | {{deposits.phone}} | {{deposits.deposit_name}} | {{deposits.actual_money}}</el-tag>
                </el-row>
              </div>
              <el-row v-if="diy_tatus==0 && diy_id>0" style="line-height: 28px;text-align: left;margin-top:20px;">
                <el-col :span="8">
                  状态：
                </el-col>
                <el-col :span="8">
                   <el-radio v-model="check_info.diy_tatus" label="1">通过</el-radio>
                </el-col>
                <el-col :span="8">
                   <el-radio v-model="check_info.diy_tatus" label="3">拒绝</el-radio>
                </el-col>
              </el-row>
              <el-row v-if="diy_tatus==0 && check_info.diy_tatus==3 && diy_id>0" style="line-height: 28px;text-align: left;margin-top:20px;">
                <el-col :span="8">
                  拒绝理由：
                </el-col>
                <el-col :span="16">
                   <el-input
                      type="textarea"
                      :rows="4"
                      placeholder="请输入拒绝理由"
                      v-model="check_info.diy_reason">
                    </el-input>
                </el-col>
              </el-row>
              
            </div>
            <div style=";padding: 10px 0;text-align: -webkit-center;">
              <!-- <el-button type="primary" style="width:270px;margin-top:40px" @click="finish_vote">完成创建</el-button> -->
              <el-row class="finish_box">
                <el-col :span="12">
                  <el-button class="save_btn" type="primary" @click="finish_vote">保存</el-button>
                </el-col>
                <el-col :span="12">
                  <el-button class="save_btn" type="primary" @click="save_print(false)">保存并打印</el-button>
                </el-col>
              </el-row>
            </div>
          </div>


          <!-- 弹出层 -->
          <el-dialog zIndex="9999999" title="选择押金" :center="true" :visible.sync="choose_diy_depositDialog" :close-on-click-modal="false" width="850px">
            <el-row>
              <el-col :span="24">
                <span>筛选：</span>
                <el-input class="search_width" v-model="deposit_search_val" size="small" maxlength="10" placeholder="请输入搜索内容"></el-input>
                <el-select class="search_width" v-model="deposit_search_type" placeholder="请选择" size="small">
                  <el-option
                    v-for="item in options"
                    :key="item.value"
                    :label="item.label"
                    :value="item.value">
                  </el-option>
                </el-select>
                &nbsp;&nbsp;&nbsp;&nbsp;
                <el-button type="primary" icon="el-icon-search" @click="deposit_search_list">查询</el-button>
              </el-col>
            </el-row>
            <el-table
              class="list_table"
              :data="deposit_data"
              style="width:100%"
              :height="500">
              <el-table-column
                prop="name"
                label="姓名"
                min-width="100">
              </el-table-column>
              <el-table-column
                prop="phone"
                label="手机号码"
                min-width="150">
              </el-table-column>
              <el-table-column
                prop="address"
                label="地址"
                min-width="180">
              </el-table-column>
              <el-table-column
                prop="deposit_name"
                label="押金项目"
                min-width="120">
              </el-table-column>
              <el-table-column
                prop="actual_money"
                label="押金金额"
                min-width="120">
              </el-table-column>
              <el-table-column
                label="操作"
                width="120">
                <template slot-scope="scope">
                  <el-button type="text" size="small" @click.native.prevent="bindDeposit(scope.$index, deposit_data)">绑定</el-button>
                </template>
              </el-table-column>
            </el-table>

            <div style="width: 100%;text-align: -webkit-center;padding: 20px 0;">
              <el-footer style="padding: 0;">
                <div v-show="deposit_total_page>0" class="page_msg">
                  <el-pagination
                    background
                    layout="prev, pager, next"
                    :page-count="deposit_total_page"
                    :current-page="deposit_page"
                    @current-change="deposit_current_change"
                  >
                  </el-pagination>
                </div>
              </el-footer>
            </div>
          </el-dialog>



          <!-- 弹出层 -->
          <el-dialog :title="choose_title" :visible.sync="dialogFormVisible" width="450px">
            <el-row>
              <el-col :span="12">
                <el-input class="choose_dialog_input"
                          type="text"
                          placeholder="请输入内容"
                          v-model="choose_val"
                          size="mini">
                </el-input>
              </el-col>
              <el-col :span="2">
                &nbsp;
              </el-col>
              <el-col :span="10">
                <el-button class="true_input" size="mini"  type="primary" @click="clickUse(0)">确认使用填写内容</el-button>
              </el-col>
            </el-row>


            <el-row style="padding: 10px 0;">
              <el-col :span="12">
                <el-input class="choose_dialog_input"
                          type="text"
                          placeholder="请输入搜索内容"
                          v-model="search_val"
                          size="mini">
                </el-input>
              </el-col>
              <el-col :span="2">
                &nbsp;
              </el-col>
              <el-col :span="10">
                <el-button class="true_input" size="mini"  type="primary" @click="search">点击搜索</el-button>
              </el-col>
            </el-row>

            <el-table
              class="list_table"
              :data="choose_data"
              style="width:100%"
              :height="400">
              <el-table-column
                prop="choose_info"
                label="所选信息"
                min-width="300">
              </el-table-column>
              <el-table-column
                label="操作"
                width="150">
                <template slot-scope="scope">
                  <el-button type="text" size="small" @click.native.prevent="clickTrue(scope.$index, choose_data)">点击选中</el-button>
                </template>
              </el-table-column>
            </el-table>

            <div style="width: 100%;text-align: -webkit-center;padding: 20px 0;">
              <el-footer style="padding: 0;">
                <div v-show="total_page>0" class="page_msg">
                  <el-pagination
                    background
                    layout="prev, pager, next"
                    :page-count="total_page"
                    :current-page="page"
                    @current-change="current_change"
                  >
                  </el-pagination>
                </div>
              </el-footer>
            </div>
          </el-dialog>

        </div>
      </div>
    </div>
</template>

<script>
  export default {
    name: 'add_template',
    data() {
      return {
        choose_diy_depositDialog: false,
        deposit_data: [],
        deposit_total_page: 1,
        deposit_page: 1,
        deposit_search_type: 'phone',
        deposit_search_val: '',
        choose_type: 'txt',
        choose_val: '',
        choose_index: '',
        page: 1,
        total_page: 1,
        pagerCount: 3,
        choose_data: [],
        dialogFormVisible: false,
        choose_title: '选择',
        floor_list: [],
        owner_list: [],
        template_img: '',
        template_img_box: '',
        template_width: '800px',
        zIndexMax: 3,
        rects: [],
        template_img_val: '', // 上传的背景图片
        template_title: '', // 模板标题
        options: [{
          value: 'phone',
          label: '手机号码'
        }, {
          value: 'room_addrss',
          label: '业主房间号'
        }, {
          value: 'name',
          label: '业主姓名'
        }],
        loading: false,
        diy_id: '',
        template_id: '',
        is_click: false,
        key_num: 0,
        custom_write: {},
        paths: '',
        search_val: '',
        hkey_root: 'HKEY_CURRENT_USER',
        hkey_path: '\\Software\\Microsoft\\Internet Explorer\\PageSetup\\',
        hkey_key: '',
        check_info: {
          diy_id: 0,
          diy_tatus: 0,
          diy_reason: ''
        },
        diy_tatus: 0,
        bind_deposit_info: [],
        owner_identity_options: [{
          value: '业主',
          label: '业主'
        }, {
          value: '家属',
          label: '家属'
        }, {
          value: '租客',
          label: '租客'
        }]
      }
    },
    mounted () {
      console.log('mounted', 1);
      this.template_id = this.$route.query.template_id;
      this.diy_id = this.$route.query.diy_id;
      this.check_info.diy_id = this.diy_id;
      this.paths = this.$route.query.paths;
      if (this.template_id>0) {
        let param = {};
        param['template_id'] = this.template_id;
        this.templateDetail(param);
      } else if(this.diy_id>0) {
        let param = {};
        param['diy_id'] = this.diy_id;
        this.templateWriteDetail(param);
      } else {
        this.$message({
          type: 'info',
          message: '缺少必要参数'
        });
        this.$router.replace({ path: '/template_list'});
      }
    },
    methods: {
      deposit_search_list() {
        console.log('deposit_search_list', this.deposit_search_type)
        console.log('deposit_search_list1', this.deposit_search_val)
        this.material_diy_deposit_list();
      },
      bindDeposit(index,rows) {
        let msg = rows[index];
        console.log('bindDeposit', msg);
        let param = {};
        param['deposit_id'] = msg['deposit_id'];
        this.add_bind_material_diy_deposit(param);
      },
      deposit_current_change(val) {
        this.deposit_page = val;
        console.log(`当前页: ${val}`);
        console.log(`当前页1: `,this.page);
        this.material_diy_deposit_list()
      },
      choose_diy_deposit() {
        console.log('diy_tatus1', this.diy_tatus);
        this.choose_diy_depositDialog = true;
        this.deposit_search_type = 'phone';
        this.deposit_search_val = '';
        this.material_diy_deposit_list();
      },
      // 解绑
      handleTagClose(info) {
        console.log('info', info);
        let param = {};
        if (info['bind_id']) {
          param['bind_id'] = info['bind_id'];
        }
        if (info['diy_id']) {
          param['diy_id'] = info['diy_id'];
        } else {
          param['diy_id'] = this.diy_id;
        }
        if (info['deposit_id']) {
          param['deposit_id'] = info['deposit_id'];
        }
        this.del_bind_material_diy_deposit(param);
      },
      // 获取需要选的信息
      async material_diy_deposit_list() {
        let param = {};
        param['page'] = this.deposit_page;
        param['search_type'] = this.deposit_search_type;
        param['search_val'] = this.deposit_search_val;
        let res = await this.$api.material_diy_deposit_list(param);
        if (res) {
          this.deposit_data = res.list;
          this.deposit_total_page = res.total_page;
        }
        console.log('chooseMsg', this.choose_data);
      },
      // 绑定
      async add_bind_material_diy_deposit(param) {
        param['diy_id'] = this.diy_id;
        let res = await this.$api.add_bind_material_diy_deposit(param);
        if (res) {
          this.$message({
            type: 'success',
            message: '绑定成功!'
          });
          let param = {};
          param['diy_id'] = this.diy_id;
          this.templateWriteDetail(param);
          this.material_diy_deposit_list();
        }
        console.log('chooseMsg', this.choose_data);
      },
      // 解除绑定
      async del_bind_material_diy_deposit(param) {
        let res = await this.$api.del_bind_material_diy_deposit(param);
        if (res) {
          this.$message({
            type: 'success',
            message: '解绑成功!'
          });
          let param = {};
          param['diy_id'] = this.diy_id;
          this.templateWriteDetail(param);
        }
        console.log('chooseMsg', this.choose_data);
      },
      input_val(e) {
        console.log('input_val', e);
      },
      clickUse() {
        let index = this.choose_index;
        this.rects[index]['value'] = this.choose_val;
        this.dialogFormVisible = false;
      },
      clickTrue(index,rows) {
        let choose = rows[index];
        let indexs = this.choose_index;
        this.rects[indexs]['value'] = choose['msg'];
        if ('owner_choose'==this.choose_type) {
            for (let i in this.rects) {
              if (this.rects[i] && !this.rects[i]['value'] && this.rects[i]['type']=='owner_phone' && choose['phone']) {
                this.rects[i]['value'] = choose['phone'];
              } else if (this.rects[i] && !this.rects[i]['value'] && this.rects[i]['type']=='floor_choose' && choose['floor_name']) {
                this.rects[i]['value'] = choose['floor_name'];
              }
            }
        } else if ('owner_phone'==this.choose_type) {
          for (let i in this.rects) {
            if (this.rects[i] && !this.rects[i]['value'] && this.rects[i]['type']=='owner_choose' && choose['name']) {
              this.rects[i]['value'] = choose['name'];
            } else if (this.rects[i] && !this.rects[i]['value'] && this.rects[i]['type']=='floor_choose' && choose['floor_name']) {
              this.rects[i]['value'] = choose['floor_name'];
            }
          }
        }
        this.dialogFormVisible = false;
      },
      template_add(info, index) {
        this.dialogFormVisible = true;
        this.choose_type = info['type'];
        this.choose_index = index;
        this.choose_val = info['value'];
        this.page = 1;
        this.choose_data = [];
        this.search_val = '';
        this.chooseMsg()
      },
      template_identity_add(info, index) {

      },
      search() {
        let search_val = this.search_val
        if (!search_val) {
          this.$message({
            type: 'info',
            message: '请填写搜索内容!'
          });
        } else {
          this.chooseMsg()
        }
      },
      // 获取需要选的信息
      async chooseMsg() {
        let param = {};
        param['type'] = this.choose_type;
        param['page'] = this.page;
        param['search_val'] = this.search_val;
        let res = await this.$api.chooseMsg(param);
        if (res) {
          this.choose_data = res.list;
          this.total_page = res.total_page;
        }
        console.log('chooseMsg', this.choose_data);
      },
      current_change(val) {
        this.page = val;
        console.log(`当前页: ${val}`);
        console.log(`当前页1: `,this.page);
        let param = {};
        param['type'] = this.choose_type;
        this.chooseMsg(param)
      },
      selectChange(index) {
        console.log('selectChangeVal', this.rects[index]);
        if (-1 == this.rects[index]['value']) {
          if (!this.custom_write) {
            this.custom_write = {};
          }
          this.custom_write[index] = true;
        }
        console.log('custom_write', this.custom_write);
      },
      custom_write_click(index) {
        console.log('custom_write_click', index);
        this.custom_write[index] = true;
      },
      custom_write_no(index) {
        console.log('custom_write_no', index);
        if (!this.custom_write) {
          this.custom_write = {};
        }
        this.custom_write[index] = false;
        console.log('custom_write1', this.custom_write);
      },
      date_choose(index) {
        console.log('date_choose', index);
        // this.$refs.choose_data[index].click();
      },
      return_vote_list_add: function () {
        if (this.paths && 'write_list'==this.paths && this.template_id) {
          this.$router.replace({ path: '/write_list', query: { template_id: this.template_id}});
        } else {
          this.$router.replace({ path: '/template_list'});
        }
      },
      close_block(index) {
        console.log('close_block',index);
        this['rects'][index]['is_close'] = true;
        this.rects.splice(index,1);
      },
      // 获取详情
      async templateDetail(param) {
        let res = await this.$api.templateDetail(param);
        if (res) {
          console.log(`templateDetail: `, res);
          this.rects = res.template_content;
          console.log(`rects: `, this.rects);
          this.template_title = res.template_title;
          this.template_img_val = res.template_img;
          this.template_img = 'url('+res.template_img_path+')';
          this.template_img_box = res.template_img_path;
          if (res.template_width) {
            this.template_width = res.template_width;
          }
        }
      },
      // 获取详情
      async templateWriteDetail(param, is_print=false, node='') {
        let res = await this.$api.templateWriteDetail(param);
        if (res) {
          console.log(`templateDetail: `, res);
          this.rects = res.diy_value;
          console.log(`rects: `, this.rects);
          this.template_title = res.title;
          this.template_img_val = res.template_img;
          this.template_img = 'url('+res.template_img_path+')';
          this.template_img_box = res.template_img_path;
          this.template_id = res.template_id;
          this.diy_tatus = res.diy_tatus;
          this.bind_deposit_info = res.bind_deposit_info;
          if (res.template_width) {
            this.template_width = res.template_width;
          }
          if (is_print) {
            node.diy_id = res.id;
            console.log('打印------------',11)
            setTimeout(function() {
              node.save_print(true);
            },1000);
          }
        }
      },
      // 编辑
      async editDiyValue(param) {
        let res = await this.$api.editDiyValue(param);
        let _this=this;
        if (res) {
          _this.$message({
            type: 'success',
            message: '修改成功!'
          });
          _this.$router.replace({ path: '/write_list', query: { template_id: this.template_id}});
        } else if (res.errorMsg) {
          _this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        return res;
      },
      // 添加填写信息
      async addDiyValue(param, is_print=false, node='') {
        let res = await this.$api.addDiyValue(param);
        let _this=this;
        if (res.diy_id && is_print) {
          let param = {};
          param['diy_id'] = res.diy_id;
          this.$router.replace({ path: '/template_write', query: { diy_id: res.diy_id, 'paths': 'write_list' }});
          this.templateWriteDetail(param, is_print, node);
          return res;
        } else {
          _this.$router.replace({ path: '/write_list', query: { template_id: this.template_id}});
        }
        if (res) {
          _this.$message({
            type: 'success',
            message: '添加成功!'
          });
        } else if (res.errorMsg) {
          _this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        return res;
      },
      finish_vote: function(e) {
        console.log('rects结果：',this.rects);
        console.log('template_img_val结果：',this.template_img_val);
        console.log('template_title结果：',this.template_title);
        if (!this.template_title) {
          console.log('err：',1);
          this.$message({
            message: '请输入模板标题',
            type: 'warning'
          });
          return false;
        }
        if (!this.template_img_val) {
          this.$message({
            message: '请上传背景图片',
            type: 'warning'
          });
          return false;
        }
        if (!this.rects) {
          this.$message({
            message: '最少选择一个选框',
            type: 'warning'
          });
          return false;
        }
        let param = {};
        param['diy_value'] = this.rects;
        param['template_img'] = this.template_img_val;
        param['template_title'] = this.template_title;
        param['template_width'] = this.template_width;
        param['template_id'] = this.template_id;
        console.log('param：',param);
        if (this.diy_id && this.diy_id>0) {
          param['diy_id'] = this.diy_id;
          if (this.diy_tatus==0 && this.check_info.diy_tatus) {
            param['diy_tatus'] = this.check_info.diy_tatus;
            if (3==param['diy_tatus'] && !this.check_info.diy_reason) {
                if (!this.template_img_val) {
                  this.$message({
                    message: '审核拒绝请填写理由',
                    type: 'warning'
                  });
                  return false;
                }
            } else if (3==param['diy_tatus']) {
              param['diy_reason'] = this.check_info.diy_reason;
            }
          }

          this.editDiyValue(param);
        } else {
          this.addDiyValue(param);
        }
      },
      up_img: function() {
        console.log('触发上传图片')
        this.$refs.tempUploadFile.click();
      },
      focus_title(e) {
        console.log('focus_title')
        if(e.target && this.vote_title_placeholder){
          this.vote_title_placeholder = '';
        }
      },
      blur_title(e) {
        if(e.target && !this.vote_title_placeholder){
          this.vote_title_placeholder = '请输入表单标题';
        }
      },
      //
      PageSetup_Null() {
        try{
          let RegWsh = new ActiveXObject("WScript.Shell") ;
          this.hkey_key = "header";
          RegWsh.RegWrite (this.hkey_root + this.hkey_path + this.hkey_key,"") ;
          this.hkey_key = "footer" ;
          RegWsh.RegWrite(this.hkey_root + this.hkey_path + this.hkey_key,"") ;
        }
        catch(e){}
      },
      save_print(is_print) {
        var _this = this;
        if (!this.template_title) {
          console.log('err：',1);
          this.$message({
            message: '请输入模板标题',
            type: 'warning'
          });
          return false;
        }
        if (!this.template_img_val) {
          this.$message({
            message: '请上传背景图片',
            type: 'warning'
          });
          return false;
        }
        if (!this.rects) {
          this.$message({
            message: '最少选择一个选框',
            type: 'warning'
          });
          return false;
        }
        let param = {};
        param['diy_value'] = this.rects;
        param['template_img'] = this.template_img_val;
        param['template_title'] = this.template_title;
        param['template_width'] = this.template_width;
        param['template_id'] = this.template_id;
        let res='';
        let diy_id = 0;
        if (is_print) {
          this.PageSetup_Null() ;
          if (window.PrePrint != null) window.PrePrint();
          try{
            print.portrait   =  false    ;//横向打印
          }catch(e){
            // alert("不支持此方法");
          }
          var bdhtml = window.document.body.innerHTML;//获取当前页的html代码
          // var sprnstr="<!--begin-->";//设置打印开始区域
          // var eprnstr="<!--end-->";//设置打印结束区域
          // var prnhtml=bdhtml.substring(bdhtml.indexOf(sprnstr)); //从开始代码向后取html
          // var prnhtml=prnhtml.substring(0,prnhtml.indexOf(eprnstr));//从结束代码向前取html
          var prnhtml = this.$refs.list_box.innerHTML;//从结束代码向前取html
          window.document.body.innerHTML=prnhtml;
          window.print();
          setTimeout("window.location.reload();", 80);
          window.document.body.innerHTML=bdhtml;
          // PageSetup_Default() ;
        } else if (this.diy_id && this.diy_id>0) {
          param['diy_id'] = this.diy_id;
          res = this.editDiyValue(param);
          if (res) {
            this.PageSetup_Null() ;
            if (window.PrePrint != null) window.PrePrint();
            try{
              print.portrait   =  false    ;//横向打印
            }catch(e){
              // alert("不支持此方法");
            }
            var bdhtml = window.document.body.innerHTML;//获取当前页的html代码
            // var sprnstr="<!--begin-->";//设置打印开始区域
            // var eprnstr="<!--end-->";//设置打印结束区域
            // var prnhtml=bdhtml.substring(bdhtml.indexOf(sprnstr)); //从开始代码向后取html
            // var prnhtml=prnhtml.substring(0,prnhtml.indexOf(eprnstr));//从结束代码向前取html
            var prnhtml = this.$refs.list_box.innerHTML;//从结束代码向前取html
            window.document.body.innerHTML=prnhtml;
            window.print();
            setTimeout("window.location.reload();", 80);
            window.document.body.innerHTML=bdhtml;
            // PageSetup_Default() ;
          }
        } else {
          res = this.addDiyValue(param, true, this);
        }
      }
    }
  }
</script>
